import{_ as n,a0 as a,w as l,s as h,ao as p,I as d,x as o,a1 as e,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux有問必答：如何修復“sshd error: could not load host key” | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何修復“sshd error: could not load host key” | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何修復“sshd error: could not load host key” | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何修復“sshd error: could not load host key” | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141022 Linux FAQs with Answers--How to fix sshd error--could not load host key","title":"Linux有問必答：如何修復“sshd error: could not load host key”","tag":"201412","desc":""},"relativePath":"201412/20141022 Linux FAQs with Answers--How to fix sshd error--could not load host key.md","filePath":"[post].md"}'),i={name:"201412/20141022 Linux FAQs with Answers--How to fix sshd error--could not load host key.md"};function u(c,s,k,S,_,m){const t=a("Link");return l(),h("div",null,[s[11]||(s[11]=p(`<h1 id="linux有問必答-如何修復-sshd-error-could-not-load-host-key" tabindex="-1">Linux有問必答：如何修復“sshd error: could not load host key” <a class="header-anchor" href="#linux有問必答-如何修復-sshd-error-could-not-load-host-key" aria-label="Permalink to “Linux有問必答：如何修復“sshd error: could not load host key””">​</a></h1><blockquote><p><strong>問題</strong>：當我嘗試SSH到一台遠程服務器時，SSH客户端登陸失敗並提示“Connection closed by X.X.X.X”。在SSH服務器那端，我看到這樣的錯誤消息：“sshd error: could not load host key.”。這發生了什麼問題，我怎樣才能修復該錯誤？</p></blockquote><p>該SSH連接錯誤的詳細症狀如下。</p><p><strong>SSH客户端方面</strong>：當你嘗試SSH到一台遠程主機時，你沒有看見登錄屏幕，你的SSH連接就立即關閉，並提示此消息：“Connection closed by X.X.X.X”。</p><p><strong>SSH服務器方面</strong>：在系統日誌中，你看到如下錯誤消息（如，在Debian/Ubuntu上，/var/log/auth.log）。</p><pre><code>Oct 16 08:59:45 openstack sshd[1214]: error: Could not load host key: /etc/ssh/ssh_host_rsa_key
Oct 16 08:59:45 openstack sshd[1214]: error: Could not load host key: /etc/ssh/ssh_host_dsa_key
Oct 16 08:59:45 openstack sshd[1214]: error: Could not load host key: /etc/ssh/ssh_host_ecdsa_key
Oct 16 08:59:45 openstack sshd[1214]: fatal: No supported key exchange algorithms [preauth]
</code></pre><p>導致該問題的根源是，sshd守護進程不知怎麼地不能加載SSH主機密鑰了。</p><p>當OpenSSH服務器第一次安裝到Linux系統時，SSH主機密鑰應該會自動生成以供後續使用。如果，不管怎樣，密鑰生成過程沒有成功完成，那就會導致這樣的SSH登錄問題。</p><p>讓我們檢查能否在相應的地方找到SSH主機密鑰。</p><pre><code>$ ls -al /etc/ssh/ssh*key 
</code></pre><p><img src="https://farm4.staticflickr.com/3931/15367231099_61b9087256_z.jpg" alt=""></p><p>如果SSH主機密鑰在那裏找不到，或者它們的大小被截斷成為0（就像上面那樣），你需要從頭開始重新生成主機密鑰。</p><h3 id="重新生成ssh主機密鑰" tabindex="-1">重新生成SSH主機密鑰 <a class="header-anchor" href="#重新生成ssh主機密鑰" aria-label="Permalink to “重新生成SSH主機密鑰”">​</a></h3><p>在Debian、Ubuntu或其衍生版上，你可以使用dpkg-reconfigure工具來重新生成SSH主機密鑰，過程如下：</p><pre><code>$ sudo rm -r /etc/ssh/ssh*key
$ sudo dpkg-reconfigure openssh-server 
</code></pre><p><img src="https://farm4.staticflickr.com/3931/15551179631_363e6a9047_z.jpg" alt=""></p><p>在CentOS、RHEL或Fedora上，你所要做的是，刪除現存（有問題的）密鑰，然後重啓sshd服務。</p><pre><code>$ sudo rm -r /etc/ssh/ssh*key
$ sudo systemctl restart sshd
</code></pre><p>另外一個重新生成SSH主機密鑰的方式是，使用ssh-keygen命令來手動生成。</p><pre><code>$ sudo ssh-keygen -t rsa -f /etc/ssh/ssh_host_rsa_key
$ sudo ssh-keygen -t dsa -f /etc/ssh/ssh_host_dsa_key
$ sudo ssh-keygen -t ecdsa -f /etc/ssh/ssh_host_ecdsa_key 
</code></pre><p><img src="https://farm6.staticflickr.com/5603/15367844767_cdfd9716c8_z.jpg" alt=""></p><p>在生成新的SSH主機密鑰後，確保它們能在/etc/ssh目錄中找到。此時，不必重啓sshd服務。</p><pre><code> $ ls -al /etc/ssh/ssh*key 
</code></pre><p>現在，再試試SSH到SSH服務器吧，看看問題是否已經離你而去了。</p><hr>`,25)),d("p",null,[s[1]||(s[1]=o("via: ",-1)),e(t,{href:"http://ask.xmodulo.com/sshd-error-could-not-load-host-key.html"},{default:r(()=>[...s[0]||(s[0]=[o("http://ask.xmodulo.com/sshd-error-could-not-load-host-key.html",-1)])]),_:1})]),d("p",null,[s[4]||(s[4]=o("譯者：",-1)),e(t,{href:"https://github.com/GOLinux"},{default:r(()=>[...s[2]||(s[2]=[o("GOLinux",-1)])]),_:1}),s[5]||(s[5]=o(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:r(()=>[...s[3]||(s[3]=[o("wxy",-1)])]),_:1})]),d("p",null,[s[8]||(s[8]=o("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...s[6]||(s[6]=[o("LCTT",-1)])]),_:1}),s[9]||(s[9]=o(" 原創翻譯，",-1)),e(t,{href:"http://linux.cn/"},{default:r(()=>[...s[7]||(s[7]=[o("Linux中國",-1)])]),_:1}),s[10]||(s[10]=o(" 榮譽推出",-1))])])}const g=n(i,[["render",u]]);export{x as __pageData,g as default};
